insert into public.ideas (id, title, tagline, description, problem, category, status, upvotes, downvotes, funding_goal, funding_current, backer_count, tags, features, target_audience, monetization) values
  ('10000000-0000-0000-0000-000000000001', 'NeuralNote', 'AI-powered meeting notes that actually understand context', 'Meetings produce mountains of notes that nobody reads. Traditional note-taking apps capture words but miss meaning.', 'Meetings produce mountains of notes that nobody reads.', 'AI', 'FUNDING', 2847, 134, 75000, 51200, 312, array['ai', 'productivity', 'meetings', 'nlp'], array['Auto-transcribe meetings in real-time', 'Extract action items automatically', 'Summarize by topic clusters', 'Integrate with Slack, Notion, Jira', 'Search across all past meetings semantically'], 'Remote teams and knowledge workers', 'Subscription'),
  ('10000000-0000-0000-0000-000000000002', 'SprintFlow', 'Kanban boards that learn your team''s velocity', 'Engineering teams waste hours in planning ceremonies that could be automated with historical data.', 'Planning ceremonies are manual and inefficient.', 'PRODUCTIVITY', 'VOTING', 1923, 89, 50000, 0, 0, array['productivity', 'agile', 'kanban', 'teams'], array['AI sprint planning based on velocity', 'Auto-assign based on skill matrix', 'Burndown predictions', 'Slack & GitHub integration', 'Custom workflow automation'], 'Software development teams', 'Subscription'),
  ('10000000-0000-0000-0000-000000000003', 'DietDrop', 'Personalized nutrition plans powered by your DNA data', 'Generic diet advice fails because everyone''s metabolism is different. Most apps give the same advice to everyone.', 'Generic diet advice fails.', 'HEALTH', 'IN_DEV', 3412, 201, 100000, 87300, 567, array['health', 'nutrition', 'dna', 'ai'], array['Connect DNA test results', 'Generate personalized meal plans', 'Track macros and micronutrients', 'Recipe suggestions based on genetics', 'Grocery list auto-generation'], 'Health-conscious individuals', 'Subscription'),
  ('10000000-0000-0000-0000-000000000004', 'ArenaLobby', 'Skill-matched gaming sessions with real money stakes', 'Casual gamers can''t compete on mainstream platforms. Skill gaps ruin the fun.', 'Skill gaps ruin competitive gaming.', 'GAMING', 'LIVE', 5621, 312, 150000, 150000, 1204, array['gaming', 'esports', 'competitive', 'wagering'], array['ELO-based matchmaking', 'Secure escrow for stakes', 'Anti-cheat verification', 'Multi-game support', 'Tournament brackets'], 'Competitive gamers 18+', 'Transaction fees'),
  ('10000000-0000-0000-0000-000000000005', 'LocalPulse', 'Hyperlocal community events with skill-based matching', 'Local communities are fragmented across Facebook groups, Nextdoor, and Meetup. Coordination is chaos.', 'Local community coordination is fragmented.', 'SOCIAL', 'VOTING', 987, 45, 30000, 0, 0, array['social', 'community', 'local', 'events'], array['Event discovery by neighborhood', 'Skill-based volunteer matching', 'Community reputation system', 'Integration with local businesses', 'Real-time event updates'], 'Urban residents and community organizers', 'Freemium'),
  ('10000000-0000-0000-0000-000000000006', 'PayFlow', 'B2B invoicing that auto-reconciles with your accounting', 'Small businesses lose 10+ hours per week chasing invoices and reconciling books manually.', 'Manual invoicing wastes hours every week.', 'FINTECH', 'FUNDING', 2156, 98, 80000, 43200, 287, array['fintech', 'invoicing', 'accounting', 'b2b'], array['Smart invoice generation from time tracking', 'Auto-reconcile with QuickBooks/Xero', 'AI payment prediction', 'Multi-currency support', 'Automated dunning emails'], 'Freelancers and small businesses', 'Subscription'),
  ('10000000-0000-0000-0000-000000000007', 'SkillPath', 'Adaptive learning paths based on your career goals', 'Online learning is overwhelming. Learners don''t know what to learn next or in what order.', 'Learners don''t know what to learn next.', 'EDUCATION', 'IN_DEV', 4102, 187, 60000, 54800, 891, array['education', 'learning', 'ai', 'career'], array['Career goal-based curriculum', 'Adaptive difficulty adjustment', 'Peer accountability pods', 'Real project portfolio building', 'Job placement partnership network'], 'Career changers and upskilling professionals', 'Subscription'),
  ('10000000-0000-0000-0000-000000000008', 'DevReview', 'AI code review that learns your team''s standards', 'Code reviews are slow, inconsistent, and don''t scale as teams grow. Senior engineers are bottlenecks.', 'Code reviews are slow and inconsistent.', 'DEVELOPER_TOOLS', 'VOTING', 3287, 156, 45000, 0, 0, array['developer-tools', 'ai', 'code-review', 'github'], array['Learn team coding standards automatically', 'Detect security vulnerabilities', 'Performance optimization hints', 'GitHub/GitLab integration', 'Custom rule configuration'], 'Software development teams', 'Subscription'),
  ('10000000-0000-0000-0000-000000000009', 'TherapyMatch', 'Find therapists who specialize in your exact situation', 'Finding the right therapist is a painful trial-and-error process that takes months and thousands of dollars.', 'Finding the right therapist is painful.', 'HEALTH', 'VOTING', 1876, 67, 40000, 0, 0, array['health', 'mental-health', 'therapy', 'matching'], array['Specialty and approach matching', 'Insurance verification automation', 'Video sessions built-in', 'Progress tracking tools', 'Community support groups'], 'Adults seeking mental health support', 'Transaction fees'),
  ('10000000-0000-0000-0000-000000000010', 'FundFlow', 'Crowdfunding specifically for app ideas with dev matching', 'Great app ideas die because founders can''t find developers, and developers can''t find funded projects.', 'Great ideas die without the right developers.', 'FINTECH', 'BETA', 2934, 143, 90000, 72100, 445, array['fintech', 'crowdfunding', 'apps', 'developers'], array['Idea validation before funding', 'Developer bid marketplace', 'Milestone-based fund release', 'Backer updates and voting', 'Revenue sharing models'], 'Idea founders and indie developers', 'Platform fee'),
  ('10000000-0000-0000-0000-000000000011', 'GrowthOS', 'All-in-one growth toolkit for indie SaaS founders', 'Indie SaaS founders juggle 12 tools for analytics, email, A/B testing, and referrals. It''s chaos.', 'Indie founders juggle too many tools.', 'DEVELOPER_TOOLS', 'FUNDING', 1654, 78, 55000, 28900, 198, array['developer-tools', 'saas', 'growth', 'analytics'], array['Unified analytics dashboard', 'Built-in email sequences', 'A/B testing framework', 'Referral program builder', 'Revenue metrics and forecasting'], 'Indie SaaS founders', 'Subscription'),
  ('10000000-0000-0000-0000-000000000012', 'StudySync', 'Group study rooms with AI tutor integration', 'Remote studying is isolating. Students struggle with focus and lack accountability partners.', 'Remote studying is isolating.', 'EDUCATION', 'VOTING', 2198, 112, 35000, 0, 0, array['education', 'studying', 'ai', 'community'], array['Virtual study rooms with video', 'Pomodoro-based session structure', 'AI tutor on demand', 'Progress leaderboards', 'Subject-based community matching'], 'Students and lifelong learners', 'Freemium'),
  ('10000000-0000-0000-0000-000000000013', 'CarbonTrack', 'Personal carbon footprint tracker with offset marketplace', 'Individuals want to reduce their carbon footprint but have no clear way to measure or act on it.', 'No easy way to measure personal carbon footprint.', 'HEALTH', 'VOTING', 1432, 89, 25000, 0, 0, array['health', 'environment', 'sustainability', 'carbon'], array['Automatic purchase scanning for emissions', 'Transportation mode detection', 'Verified offset marketplace', 'Community challenges', 'Business travel integration'], 'Environmentally conscious consumers', 'Freemium'),
  ('10000000-0000-0000-0000-000000000014', 'SocialProof', 'Collect and display customer reviews that actually convert', 'Most review widgets are ugly, slow, and ignored. Social proof is the highest-ROI marketing tool nobody uses well.', 'Review widgets are ugly and ignored.', 'PRODUCTIVITY', 'FUNDING', 1876, 67, 40000, 22400, 156, array['productivity', 'marketing', 'reviews', 'saas'], array['One-click review collection via SMS/email', 'Video testimonial recording', 'A/B test different formats', 'CRM integrations', 'Trust badge generator'], 'E-commerce and SaaS founders', 'Subscription'),
  ('10000000-0000-0000-0000-000000000015', 'MeshNet', 'Decentralized mesh network for disaster communication', 'When disasters strike, cell towers go down first. Communities are left without communication infrastructure.', 'Cell towers fail during disasters.', 'SOCIAL', 'VOTING', 987, 34, 120000, 0, 0, array['social', 'networking', 'disaster', 'mesh', 'decentralized'], array['Bluetooth/WiFi mesh networking', 'Offline-first messaging', 'Emergency alert broadcasting', 'GPS location sharing', 'Integration with emergency services'], 'Emergency responders and disaster-prone communities', 'One-time purchase');
